"Esta app es para practicar entre clase y clase lo que vais viendo: saludos, presentarse, números, gustos… Cinco minutos al día bastan.":"Cette appli sert à pratiquer entre deux cours ce que vous voyez : saluer, se présenter, les nombres, les goûts… Cinq minutes par jour suffisent.",
"Semilla, brote, árbol":"Graine, pousse, arbre",
"Cada frase empieza como semilla. Cuando la estudias es un brote y vuelve a salir al día siguiente, a los 3, a los 7… Si la recuerdas cada vez, se hace árbol: firme. Si la fallas, vuelve mañana.":"Chaque phrase commence comme une graine. Quand tu l'étudies, c'est une pousse qui revient le lendemain, à 3 jours, à 7… Si tu t'en souviens à chaque fois, elle devient un arbre : acquise. Si tu la rates, elle revient demain.",
"Escribe, no elijas":"Écris, ne choisis pas",
"Casi siempre te pediré escribir la frase. Hay pista y opciones, pero cuentan menos. Escribir es lo que hace que se quede.":"Presque toujours je te demanderai d'écrire la phrase. Il y a un indice et des options, mais ils comptent moins. C'est écrire qui fait que ça reste.",
"tienes una ronda a medias":"tu as une série en cours",
