"ranking de la semana":"classement de la semaine",
"Cómo funciona":"Comment ça marche",
"<p>Busca a alguien por su nombre y añádelo. Con tu círculo puedes lanzar retos, proponer tareas en persona y ver su racha y progreso en el ranking.</p><p>No hace falta que te acepten: es una lista tuya, como los contactos.</p>":"<p>Cherche quelqu'un par son prénom et ajoute-le. Avec ton cercle tu peux lancer des défis, proposer des tâches en personne et voir sa série et sa progression dans le classement.</p><p>Pas besoin d'être accepté : c'est ta liste à toi, comme les contacts.</p>",
"<p>Eliges a alguien y respondes 6 frases de las que ya conoces. La otra persona recibe las mismas 6 y gana quien acierte más.</p><p>El resultado aparece en Historia cuando los dos habéis terminado.</p>":"<p>Tu choisis quelqu'un et tu réponds à 6 phrases que tu connais déjà. L'autre personne reçoit les mêmes 6 et celui qui en réussit le plus gagne.</p><p>Le résultat apparaît dans Historia quand vous avez tous les deux terminé.</p>",
"<p>Proponle a alguien de tu círculo algo para hacer en euskera fuera de la app: pedir un café, presentaros, contar qué hicisteis ayer.</p><p>Cuando lo hagáis, cada uno marca que está hecho.</p>":"<p>Propose à quelqu'un de ton cercle quelque chose à faire en basque hors de l'appli : commander un café, vous présenter, raconter ce que vous avez fait hier.</p><p>Une fois fait, chacun marque que c'est fait.</p>",
"<p>Si marcas <b>disponible</b>, gente que no conoces puede retarte, y tú puedes pedir un reto al azar entre quienes también están disponibles.</p><p>Si os caéis bien, podéis añadiros al círculo desde Historia.</p>":"<p>Si tu coches <b>disponible</b>, des gens que tu ne connais pas peuvent te défier, et tu peux demander un défi au hasard parmi ceux qui sont aussi disponibles.</p><p>Si vous vous entendez bien, vous pouvez vous ajouter au cercle depuis Historia.</p>",
"<p>XP de los últimos 7 días. Cada frase acertada en una ronda da 10 XP.</p><p>Cuenta todo el mundo que haya hecho al menos una ronda; si no apareces, es que aún no has practicado esta semana.</p>":"<p>XP des 7 derniers jours. Chaque phrase réussie dans une série donne 10 XP.</p><p>Tout le monde compte dès une série faite ; si tu n'apparais pas, c'est que tu n'as pas encore pratiqué cette semaine.</p>",
"<p>Retos y tareas pendientes y terminados, con quién y cómo quedaron.</p>":"<p>Défis et tâches en attente et terminés, avec qui et comment ça s'est fini.</p>",
"<p><b>Hazi</b> (semilla): frases que aún no has estudiado.</p><p><b>Ikasten</b> (brote): en estudio, vuelven a salir en tus rondas.</p><p><b>Sendo</b> (firme): las has recordado varias veces con días de por medio. Si fallas una, baja a brote y vuelve mañana.</p>":"<p><b>Hazi</b> (graine) : phrases pas encore étudiées.</p><p><b>Ikasten</b> (pousse) : en cours, elles reviennent dans tes séries.</p><p><b>Sendo</b> (acquise) : tu t'en es souvenu plusieurs fois à quelques jours d'écart. Si tu en rates une, elle redevient pousse et revient demain.</p>",
"<p>XP que ganaste cada día de los últimos siete. La racha cuenta los días seguidos con al menos una ronda.</p>":"<p>XP gagnés chaque jour sur les sept derniers. La série de jours compte les jours consécutifs avec au moins une session.</p>",
"<p>Tu posición esta semana entre quienes han practicado, tus días de práctica frente a la media, y el porcentaje de tus frases que ya está firme.</p>":"<p>Ta position cette semaine parmi ceux qui ont pratiqué, tes jours de pratique par rapport à la moyenne, et le pourcentage de tes phrases déjà acquises.</p>",
"<p>Por cada lección empezada, qué parte de sus frases tienes ya firmes.</p>":"<p>Pour chaque leçon commencée, la part de ses phrases déjà acquises.</p>",
"<p>Las frases que más veces has fallado. Con tres o más, el botón <b>Zailenak</b> te las pone solas en una ronda, sin tocar el calendario.</p>":"<p>Les phrases que tu as le plus souvent ratées. À partir de trois, le bouton <b>Zailenak</b> te les propose seules dans une série, sans toucher au calendrier.</p>",
"<p><b>Gaurko txanda</b>: lo que toca repasar hoy más unas pocas frases nuevas. Una al día basta.</p><p><b>Txanda librea</b>: 10 frases al azar de las que ya conoces, sin tocar el calendario.</p><p><b>Zailenak</b>: solo las que has fallado dos veces o más.</p>":"<p><b>Gaurko txanda</b> : ce qu'il faut réviser aujourd'hui plus quelques phrases nouvelles. Une par jour suffit.</p><p><b>Txanda librea</b> : 10 phrases au hasard parmi celles que tu connais, sans toucher au calendrier.</p><p><b>Zailenak</b> : seulement celles ratées deux fois ou plus.</p>",
