"Nor = persona, zer = cosa":"Nor = personne, zer = chose",
"Nor da? (¿quién es?) se contesta con alguien: Ane da. Zer da? (¿qué es?) se contesta con algo: liburua da.":"Nor da? (qui est-ce ?) se répond par quelqu'un : Ane da. Zer da? (qu'est-ce que c'est ?) se répond par quelque chose : liburua da.",
"Zer vs zein: ¿hay dónde elegir?":"Zer ou zein : y a-t-il un choix ?",
"Zer pregunta por algo que no conoces (zer da hau? → liburua da). Zein pregunta cuál de varios que ya tienes delante (zein da zurea? → hori). Truco: si la respuesta es señalar, es zein.":"Zer demande quelque chose que tu ne connais pas (zer da hau? → liburua da). Zein demande lequel parmi plusieurs que tu as devant toi (zein da zurea? → hori). Astuce : si la réponse consiste à montrer du doigt, c'est zein.",
"Zein también con personas":"Zein aussi avec des personnes",
"Nor da irakaslea? = ¿quién es (cómo se llama) el profesor? Zein da irakaslea? = ¿cuál de estos es el profesor? Zein vale para personas y cosas: lo que marca es la elección.":"Nor da irakaslea? = qui est (comment s'appelle) le professeur ? Zein da irakaslea? = lequel de ceux-ci est le professeur ? Zein vaut pour les personnes et les choses : ce qui compte, c'est le choix.",
"¿Quién es aquella?":"Qui est celle-là ?",
"Aquella es Miren, mi profesora.":"Celle-là, c'est Miren, ma professeure.",
"¿Y qué es esto?":"Et qu'est-ce que c'est, ça ?",
"¿Cuál es el tuyo, este o ese?":"Lequel est le tien, celui-ci ou celui-là ?",
