"La lámpara está al lado del sofá.":"La lampe est à côté du canapé.",
"El espejo está detrás de la puerta.":"Le miroir est derrière la porte.",
"La planta está delante de la ventana.":"La plante est devant la fenêtre.",
"Las sillas están en la cocina.":"Les chaises sont dans la cuisine.",
"¿Hay televisión?":"Y a-t-il une télévision ?",
"Sí, hay.":"Oui, il y en a.",
"No, no hay televisión.":"Non, il n'y a pas de télévision.",
"¿Dónde está el armario?":"Où est l'armoire ?",
"El armario está en el dormitorio.":"L'armoire est dans la chambre.",
"De la mesa: -(r)en":"De la table : -(r)en",
"mahaia → mahaiaren gainean (encima de la mesa), ohea → ohearen azpian. La cosa de referencia lleva -ren (o -en tras consonante) y después la posposición.":"mahaia → mahaiaren gainean (sur la table), ohea → ohearen azpian. La chose de référence prend -ren (ou -en après consonne), puis la postposition.",
"¿Hay…? Ba al dago …-rik?":"Y a-t-il… ? Ba al dago …-rik?",
"Ba al dago telebistarik? = ¿hay televisión? Se responde Bai, badago o Ez, ez dago telebistarik. En preguntas y negaciones la cosa lleva -rik.":"Ba al dago telebistarik? = y a-t-il une télévision ? On répond Bai, badago ou Ez, ez dago telebistarik. Dans les questions et les négations, la chose prend -rik.",
"dago / daude":"dago / daude",
"Una cosa: Mahaia sukaldean dago. Varias: Aulkiak sukaldean daude. Igual que da / dira.":"Une chose : Mahaia sukaldean dago. Plusieurs : Aulkiak sukaldean daude. Comme da / dira.",
"¿Hay nevera?":"Y a-t-il un frigo ?",
"Sí, hay. Está en la cocina, al lado de la ventana.":"Oui. Il est dans la cuisine, à côté de la fenêtre.",
"¿Y televisión?":"Et une télévision ?",
"No, no hay televisión. Libros sí, ¡muchos!":"Non, il n'y a pas de télévision. Des livres oui, plein !",
