"El hospital está cerca.":"L'hôpital est près.",
"¿Qué hay en tu barrio?":"Qu'y a-t-il dans ton quartier ?",
"Hay = dago / daude":"Il y a = dago / daude",
"Okindegi bat dago = hay una panadería. Bi taberna daude = hay dos bares. No hay un verbo «haber»: es egon con lo que hay como sujeto.":"Okindegi bat dago = il y a une boulangerie. Bi taberna daude = il y a deux bars. Pas de verbe « il y a » : c'est egon avec ce qu'il y a comme sujet.",
"Cerca y lejos":"Près et loin",
"gertu (cerca) y urrun (lejos) van con dago: Geltokia urrun dago. Cerca de algo: etxetik gertu (de casa, -tik).":"gertu (près) et urrun (loin) vont avec dago : Geltokia urrun dago. Près de quelque chose : etxetik gertu (de la maison, -tik).",
"Al lado del ayuntamiento":"À côté de la mairie",
"udaletxea → udaletxearen ondoan. Misma regla que con los muebles: -(r)en + posposición.":"udaletxea → udaletxearen ondoan. Même règle qu'avec les meubles : -(r)en + postposition.",
"Hay muchas tiendas: panadería, farmacia y un supermercado.":"Il y a beaucoup de magasins : une boulangerie, une pharmacie et un supermarché.",
"¿Y bares?":"Et des bars ?",
"Sí, un bar en la plaza, muy bonito.":"Oui, un bar sur la place, très joli.",
