"Herrian · en el pueblo":"Herrian · au village",
"Dónde está: egon + -(r)en + posposición":"Où c'est : egon + -(r)en + postposition",
"Para decir dónde está algo se usa egon (dago / daude). El lugar lleva -n (sukaldean) o la cosa de referencia lleva -(r)en + gainean, azpian, ondoan… Hay = dago; no hay = ez dago …-rik.":"Pour dire où se trouve quelque chose, on utilise egon (dago / daude). Le lieu prend -n (sukaldean) ou la chose de référence prend -(r)en + gainean, azpian, ondoan… Il y a = dago ; il n'y a pas = ez dago …-rik.",
