"Responde que sí":"Réponds que oui",
"Ir y venir: -ra / -tik":"Aller et venir : -ra / -tik",
"Adónde (NORA) lleva -ra; de dónde (NONDIK) lleva -tik. joan y etorri tienen formas cortas sin auxiliar: noa / nator.":"Où l'on va (NORA) prend -ra ; d'où l'on vient (NONDIK) prend -tik. joan et etorri ont des formes courtes sans auxiliaire : noa / nator.",
"Ahora vienes de ahí":"Maintenant tu viens de là",
"Pregunta de dónde viene":"Demande d'où il/elle vient",
"Dilo de él/ella":"Dis-le de lui/elle",
"Cómo es: adjetivo + -a + da":"Comment c'est : adjectif + -a + da",
"Nolakoa da? se responde con el adjetivo después del nombre, con -a y el verbo da al final. oso / nahiko delante; baina / eta unen adjetivos.":"Nolakoa da? se répond par l'adjectif après le nom, avec -a et le verbe da à la fin. oso / nahiko devant ; baina / eta relient les adjectifs.",
"handia / txikia":"handia / txikia",
"grande / pequeño":"grand / petit",
"polita / itsusia":"polita / itsusia",
"bonito / feo":"joli / laid",
"zaharra / berria":"zaharra / berria",
"viejo / nuevo":"vieux / neuf",
"lasaia / zaratatsua":"lasaia / zaratatsua",
"tranquilo / ruidoso":"tranquille / bruyant",
"merkea / garestia":"merkea / garestia",
"barato / caro":"bon marché / cher",
"Di lo contrario":"Dis le contraire",
"Añade «y cara»":"Ajoute « et chère »",
"La cosa de referencia lleva -(r)en y después la posposición: mahaia → mahaiaren gainean, ohea → ohearen azpian.":"La chose de référence prend -(r)en puis la postposition : mahaia → mahaiaren gainean, ohea → ohearen azpian.",
"badago = sí hay / sí está. Es ba- + dago, se escribe junto. Para negar: ez dago …-rik.":"badago = oui, il y en a / oui, c'est là. C'est ba- + dago, écrit en un mot. Pour nier : ez dago …-rik.",
"No hay: ez dago + cosa con -rik: ez dago telebistarik. La -rik solo aparece en negaciones y preguntas.":"Il n'y a pas : ez dago + chose avec -rik : ez dago telebistarik. Le -rik n'apparaît que dans les négations et les questions.",
"¿Hay…? = Ba al dago …-rik? La cosa lleva -rik en la pregunta.":"Y a-t-il… ? = Ba al dago …-rik? La chose prend -rik dans la question.",
"daude = están (varios). Para uno solo: dago. Aulkiak sukaldean daude.":"daude = ils sont (plusieurs). Pour un seul : dago. Aulkiak sukaldean daude.",
"Etxeak … ditu: con «tener» el sujeto lleva -k (etxea → etxeak) y el verbo es plural si son varias cosas.":"Etxeak … ditu : avec « avoir » le sujet prend -k (etxea → etxeak) et le verbe est au pluriel s'il y a plusieurs choses.",
"No tener: ez du + cosa con -rik: ez du balkoirik.":"Ne pas avoir : ez du + chose avec -rik : ez du balkoirik.",
"noa = voy (forma corta de joan). Adónde lleva -ra: etxera noa.":"noa = je vais (forme courte de joan). La destination prend -ra : etxera noa.",
"nator = vengo (forma corta de etorri). De dónde lleva -tik: etxetik nator.":"nator = je viens (forme courte d'etorri). La provenance prend -tik : etxetik nator.",
"zoaz = vas. noa (voy), zoaz (vas), doa (va).":"zoaz = tu vas. noa (je vais), zoaz (tu vas), doa (il va).",
"zatoz = vienes. nator (vengo), zatoz (vienes), dator (viene).":"zatoz = tu viens. nator (je viens), zatoz (tu viens), dator (il vient).",
"De dónde: -tik tras vocal (Bilbotik); -dik tras -n o -l (Irundik, Madrildik).":"D'où : -tik après voyelle (Bilbotik) ; -dik après -n ou -l (Irundik, Madrildik).",
"Adónde: -ra (etxera, Bilbora); tras consonante -era (Madrilera).":"Où (direction) : -ra (etxera, Bilbora) ; après consonne -era (Madrilera).",
"eskuinera = a la derecha, ezkerrera = a la izquierda (con -ra, hacia). Está a la derecha: eskuinean dago.":"eskuinera = à droite, ezkerrera = à gauche (avec -ra, vers). C'est à droite : eskuinean dago.",
"Nolakoa da? = ¿cómo es? Se responde con adjetivo + -a + da: Etxea handia da.":"Nolakoa da? = comment c'est ? Se répond par adjectif + -a + da : Etxea handia da.",
"En plural el adjetivo también lleva -ak y el verbo es dira: pisuak garestiak dira.":"Au pluriel l'adjectif prend aussi -ak et le verbe est dira : pisuak garestiak dira.",
"nahiko = bastante, delante del adjetivo: nahiko merkea.":"nahiko = assez, devant l'adjectif : nahiko merkea.",
"gertu = cerca, urrun = lejos; van con dago: Geltokia urrun dago.":"gertu = près, urrun = loin ; ils vont avec dago : Geltokia urrun dago.",
