  "Tras vocal, -ren: Aneren liburua, amaren autoa. Tras consonante, -en: Mikelen bizikleta, Jonen etxea. Y va DELANTE de la cosa, como «el libro de Ane» al revés.": "Après voyelle, -ren : Aneren liburua, amaren autoa. Après consonne, -en : Mikelen bizikleta, Jonen etxea. Et ça se place DEVANT la chose, à l'inverse de « le livre d'Ane ».",
