  "De 20 en 20, hasta 100": "De 20 en 20, jusqu'à 100",
  "hogei (20), berrogei (2×20=40), hirurogei (3×20=60), laurogei (4×20=80), ehun (100). Lo de en medio se añade con -ta: berrogeita hamar (40+10=50), hirurogeita hamar (60+10=70).": "hogei (20), berrogei (2×20=40), hirurogei (3×20=60), laurogei (4×20=80), ehun (100). Le reste s'ajoute avec -ta : berrogeita hamar (40+10=50), hirurogeita hamar (60+10=70). Comme « quatre-vingts » en français !",
  "El número va delante y el nombre en singular": "Le nombre devant, le nom au singulier",
  "hogeita bost euro, hirurogei urte, ehun pertsona: el nombre no lleva -ak aunque sean muchos. El verbo sí es plural: ditu, daude, dira.": "hogeita bost euro, hirurogei urte, ehun pertsona : le nom ne prend pas -ak même s'il y en a beaucoup. Le verbe, lui, est au pluriel : ditu, daude, dira.",
  "Teléfonos: cifra a cifra": "Numéros de téléphone : chiffre par chiffre",
  "Lo más fácil es decir el número cifra a cifra: sei, bat, bi… También se dice en pares (hirurogeita hamabi = 72), pero cifra a cifra siempre vale.": "Le plus simple est de dire le numéro chiffre par chiffre : sei, bat, bi… On dit aussi par paires (hirurogeita hamabi = 72), mais chiffre par chiffre marche toujours.",
  "Seis, uno, dos, cuatro, cinco, cinco, siete, ocho, nueve.": "Six, un, deux, quatre, cinq, cinq, sept, huit, neuf.",
  "¿Y la dirección?": "Et l'adresse ?",
  "Calle Mayor cuarenta y dos, segundo piso.": "Kale Nagusia quarante-deux, deuxième étage.",
  "Los ojos son dos: begi urdinak (plural, -ak) + ditut. El pelo es uno: ile luzea dut.": "Les yeux sont deux : begi urdinak (pluriel, -ak) + ditut. Les cheveux, c'est une chose : ile luzea dut.",
  "Los estados de ánimo van con egon (nago, dago…) y sin -a: pozik nago, haserre dago. El carácter va con izan y -a: jatorra da.": "Les humeurs vont avec egon (nago, dago…) et sans -a : pozik nago, haserre dago. Le caractère va avec izan et -a : jatorra da.",
  "Hambre y sed van con izan: gose naiz (tengo hambre), egarri zara? (¿tienes sed?).": "Faim et soif vont avec izan : gose naiz (j'ai faim), egarri zara? (tu as soif ?).",
  "El demostrativo va detrás del nombre y el nombre sin -a: gizon hori (ese hombre), liburu hau (este libro).": "Le démonstratif suit le nom, et le nom est sans -a : gizon hori (cet homme-là), liburu hau (ce livre-ci).",
  "asko va detrás del nombre y el nombre sin -ak: lagun asko ditut, jende asko dago.": "asko suit le nom, et le nom est sans -ak : lagun asko ditut, jende asko dago.",
  "Solos llevan -a: nirea da (es mío). Delante de un nombre, sin -a: nire liburua.": "Seuls, ils prennent -a : nirea da (c'est à moi). Devant un nom, sans -a : nire liburua.",
  "De alguien: -ren tras vocal (Aneren, amaren), -en tras consonante (Mikelen, Jonen). Va delante de la cosa: Aneren liburua.": "De quelqu'un : -ren après voyelle (Aneren, amaren), -en après consonne (Mikelen, Jonen). Ça se place devant la chose : Aneren liburua.",
  "Norena da? = ¿de quién es? Respuesta: nirea / zurea, o dueño + -rena: Anerena da.": "Norena da? = à qui est-ce ? Réponse : nirea / zurea, ou propriétaire + -rena : Anerena da.",
  "hirurogei = 3×20 = 60, laurogei = 4×20 = 80. Con -ta se añade el resto: hirurogeita hamar = 70, laurogeita hamar = 90.": "hirurogei = 3×20 = 60, laurogei = 4×20 = 80. Avec -ta on ajoute le reste : hirurogeita hamar = 70, laurogeita hamar = 90.",
  "ehun = 100. Después del número, el nombre va en singular: ehun pertsona, ehun euro.": "ehun = 100. Après le nombre, le nom est au singulier : ehun pertsona, ehun euro.",
  "Tras un número el nombre va en singular (hogei euro, hirurogei urte), pero el verbo es plural: dira, ditu, daude.": "Après un nombre le nom est au singulier (hogei euro, hirurogei urte), mais le verbe est au pluriel : dira, ditu, daude.",
  "Carácter y ánimo: ser (izan) o estar (egon)": "Caractère et humeur : izan ou egon",
