  "Presente habitual: raíz + -ten/-tzen + dut: jaten dut (como), edaten dut (bebo), erosten dut (compro).": "Présent d'habitude : radical + -ten/-tzen + dut : jaten dut (je mange), edaten dut (je bois), erosten dut (j'achète).",
  "Con: -rekin tras vocal (esnearekin, kuadrillarekin), -ekin en plural (patatekin, lagunekin).": "Avec : -rekin après voyelle (esnearekin, kuadrillarekin), -ekin au pluriel (patatekin, lagunekin).",
  "nahi dut = quiero; lo que quieres va delante: kafe bat nahi dut. Zer nahi duzu? = ¿qué quieres?": "nahi dut = je veux ; ce que tu veux vient devant : kafe bat nahi dut. Zer nahi duzu? = que veux-tu ?",
  "Con bat (un/una) el nombre pierde el -a: kafea → kafe bat, pintxoa → pintxo bat.": "Avec bat (un/une) le nom perd le -a : kafea → kafe bat, pintxoa → pintxo bat.",
  "nahiago dut = prefiero: pasta nahiago dut. Para elegir: arraina ala haragia? (ala = o).": "nahiago dut = je préfère : pasta nahiago dut. Pour choisir : arraina ala haragia? (ala = ou).",
  "Cómo está la comida ahora: egon (goxoa dago, beroa dago). Cómo es siempre: izan (txokolatea gozoa da).": "Comment est le plat en ce moment : egon (goxoa dago, beroa dago). Comment il est toujours : izan (txokolatea gozoa da).",
  "Zenbat balio du? (una cosa) / zenbat balio dute? (varias). Se responde en euros: bi euro eta erdi.": "Zenbat balio du? (une chose) / zenbat balio dute? (plusieurs). On répond en euros : bi euro eta erdi.",
  "eta erdi = y medio: euro eta erdi (1,50), bi euro eta erdi (2,50).": "eta erdi = et demi : euro eta erdi (1,50), bi euro eta erdi (2,50).",
  "-ago = más: merkeagoa (más barato), garestiagoa (más caro), handiagoa (más grande).": "-ago = plus : merkeagoa (moins cher), garestiagoa (plus cher), handiagoa (plus grand).",
  "Besterik? = ¿algo más? Respuesta: Ezer ez, eskerrik asko (nada más, gracias).": "Besterik? = et avec ceci ? Réponse : Ezer ez, eskerrik asko (ce sera tout, merci).",
  "goaz = vamos (forma corta de joan). joaten gara = solemos ir (habitual): jaietan txosnetara joaten gara.": "goaz = nous allons (forme courte de joan). joaten gara = nous allons d'habitude : jaietan txosnetara joaten gara.",
  "On egin! = ¡que aproveche! Topa! / Osasuna! = ¡salud! (brindis).": "On egin! = bon appétit ! Topa! / Osasuna! = santé !",
  "Querer y preferir: nahi dut, nahiago dut": "Vouloir et préférer : nahi dut, nahiago dut",
  "nahi dut = quiero, nahiago dut = prefiero. Lo que quieres va delante: kafe bat nahi dut, pasta nahiago dut. Con un verbo, el verbo va en su forma básica: jan nahi dut (quiero comer). Preguntar: Zer nahi duzu? Negar: ez dut nahi.": "nahi dut = je veux, nahiago dut = je préfère. Ce que tu veux vient devant : kafe bat nahi dut, pasta nahiago dut. Avec un verbe, le verbe reste à sa forme de base : jan nahi dut (je veux manger). Demander : Zer nahi duzu? Nier : ez dut nahi.",
