  "Jugar a: pilotan / futbolean jokatzen dut (la actividad lleva -n).": "Jouer à : pilotan / futbolean jokatzen dut (l'activité prend -n).",
  "Con: -ekin (plural: lagunekin), -rekin tras vocal (familiarekin, Anerekin). Norekin? = ¿con quién?": "Avec : -ekin (pluriel : lagunekin), -rekin après voyelle (familiarekin, Anerekin). Norekin? = avec qui ?",
  "Medio de transporte: -z: trenez (en tren), kotxez (en coche), oinez (a pie).": "Moyen de transport : -z : trenez (en train), kotxez (en voiture), oinez (à pied).",
  "A un/una: X batera: kontzertu batera (a un concierto), hondartza batera.": "À un/une : X batera : kontzertu batera (à un concert), hondartza batera.",
  "ari du = está (ahora mismo): euria ari du (está lloviendo), elurra ari du (está nevando).": "ari du = c'est en train (maintenant) : euria ari du (il pleut), elurra ari du (il neige).",
