  "eguzkia dago = hace sol (literalmente «hay sol»); lainotuta dago = está nublado.": "eguzkia dago = il y a du soleil (littéralement « il y a soleil ») ; lainotuta dago = c'est nuageux.",
  "haizea dabil = hace viento (el viento «anda»; dabil = anda, de ibili).": "haizea dabil = il y a du vent (le vent « marche » ; dabil = il marche, d'ibili).",
  "Futuro del tiempo: bihar euria egingo du (mañana lloverá), eguraldi ona egingo du.": "Météo au futur : bihar euria egingo du (demain il pleuvra), eguraldi ona egingo du.",
  "Hogei gradu daude = hay veinte grados (grados en singular tras el número, verbo plural).": "Hogei gradu daude = il fait vingt degrés (degré au singulier après le nombre, verbe au pluriel).",
  "Invitar: nahi duzu etorri? (¿quieres venir?). En preguntas informales el verbo puede ir detrás.": "Inviter : nahi duzu etorri? (tu veux venir ?). Dans les questions informelles le verbe peut venir après.",
  "ezin dut = no puedo; ezin naiz joan = no puedo ir. Ezin va delante del auxiliar.": "ezin dut = je ne peux pas ; ezin naiz joan = je ne peux pas y aller. Ezin se place devant l'auxiliaire.",
