  "Tener fiebre / resfriado: sukarra dut, hotzeria dut (con ukan, como «tener»).": "Avoir de la fièvre / un rhume : sukarra dut, hotzeria dut (avec ukan, comme « avoir »).",
  "El tiempo: ari du, egiten du, dago": "La météo : ari du, egiten du, dago",
  "Lo que cae ahora mismo va con ari du: euria ari du, elurra ari du. Lo que «hace» va con egiten du: hotz egiten du, bero egiten du, eguraldi ona egiten du. Lo que hay o cómo está el cielo, con dago: eguzkia dago, lainotuta dago. El viento anda: haizea dabil. Futuro: egingo du.": "Ce qui tombe en ce moment va avec ari du : euria ari du, elurra ari du. Ce qu'il « fait » va avec egiten du : hotz egiten du, bero egiten du, eguraldi ona egiten du. Ce qu'il y a ou l'état du ciel, avec dago : eguzkia dago, lainotuta dago. Le vent marche : haizea dabil. Futur : egingo du.",
