  "ukan en pasado con una cosa: nuen, zenuen, zuen, genuen, zenuten, zuten. Con varias: nituen, zenituen, zituen, genituen, zenituzten, zituzten. Solo significa «tenía» (txakur bat nuen); con un verbo delante es el pasado con objeto (ikusi nuen = vi). Negativo: ez nuen …-rik.": "ukan au passé avec une chose : nuen, zenuen, zuen, genuen, zenuten, zuten. Avec plusieurs : nituen, zenituen, zituen, genituen, zenituzten, zituzten. Seul, il signifie « avait » (txakur bat nuen) ; avec un verbe devant, c'est le passé avec complément (ikusi nuen = j'ai vu). Négatif : ez nuen …-rik.",
