  "De pequeño/a jugaba en la calle.": "Enfant, je jouais dans la rue.",
  "La abuela hacía pan.": "Grand-mère faisait du pain.",
  "En verano íbamos al caserío.": "En été, nous allions à la ferme.",
  "Ponlo en pasado y en «ellos»": "Mets-le au passé et à « ils »",
  "Me gustaba: zitzaidan, zitzaizkidan": "J'aimais : zitzaidan, zitzaizkidan",
  "El pasado de gustatzen zait es gustatzen zitzaidan (me gustaba). Con varias cosas, zitzaizkidan (me gustaban). Las personas cambian como en presente: zitzaizun (te gustaba), zitzaion (le gustaba), zitzaigun (nos gustaba). Negativo: ez zitzaidan gustatzen.": "Le passé de gustatzen zait est gustatzen zitzaidan (j'aimais). Avec plusieurs choses, zitzaizkidan. Les personnes changent comme au présent : zitzaizun (tu aimais), zitzaion (il/elle aimait), zitzaigun (nous aimions). Négatif : ez zitzaidan gustatzen.",
