  "Con hasi (empezar), bukatu (terminar) y jakin (saber) el otro verbo va en -tzen / -ten: ikasten hasi nintzen, lanean hasi naiz, igeri egiten badakit, ez dakit gidatzen. hasi y bukatu se conjugan con izan (hasi naiz, hasi nintzen) porque no llevan objeto. jakin: dakit, dakizu, daki; en pasado nekien, zenekien, zekien. ba- delante afirma: badakit.": "Avec hasi (commencer), bukatu (finir) et jakin (savoir), l'autre verbe va en -tzen / -ten : ikasten hasi nintzen, lanean hasi naiz, igeri egiten badakit, ez dakit gidatzen. hasi et bukatu se conjuguent avec izan (hasi naiz, hasi nintzen) car ils n'ont pas d'objet. jakin : dakit, dakizu, daki ; au passé nekien, zenekien, zekien. ba- devant affirme : badakit.",
