  "Cuando hay tres participantes (quién, qué y a quién), el auxiliar los junta: eman dit (me ha dado), eman dizut (te he dado), eman diot (le he dado), eman digu (nos ha dado). Es el nor-nori-nork.": "Quand il y a trois participants (qui, quoi et à qui), l'auxiliaire les réunit : eman dit (il/elle m'a donné), eman dizut (je t'ai donné), eman diot (je lui ai donné), eman digu (il/elle nous a donné). C'est le nor-nori-nork.",
