  "anoche": "hier soir",
  "Le he enviado un mensaje a mamá.": "J'ai envoyé un message à maman.",
  "Todavía no me ha contestado.": "Elle ne m'a pas encore répondu.",
  "Te llamo luego, ¿vale?": "Je t'appelle plus tard, d'accord ?",
  "Anoche me llamó papá.": "Hier soir papa m'a appelé(e).",
  "Os enviaré las fotos.": "Je vous enverrai les photos.",
  "Le he dado las gracias por la ayuda.": "Je l'ai remercié(e) pour son aide.",
  "¿Has llamado a la abuela?": "Tu as appelé grand-mère ?",
  "Sí, y la he felicitado.": "Oui, et je l'ai félicitée.",
  "Nos han escrito un correo electrónico.": "Ils nous ont écrit un courriel.",
  "Te he enviado un mensaje de voz; ¿lo has oído?": "Je t'ai envoyé un message vocal ; tu l'as écouté ?",
  "Nos han invitado a cenar.": "Ils nous ont invités à dîner.",
  "Te contesto enseguida.": "Je te réponds tout de suite.",
  "Llamar a alguien: deitu diot": "Appeler quelqu'un : deitu diot",
  "En euskera batua, deitu lleva dativo: amari deitu diot (he llamado a mamá), deituko dizut (te llamaré), aitak deitu zidan (papá me llamó).": "En basque unifié, deitu prend le datif : amari deitu diot (j'ai appelé maman), deituko dizut (je t'appellerai), aitak deitu zidan (papa m'a appelé).",
  "Dar las gracias: eskerrak eman dizkiot": "Remercier : eskerrak eman dizkiot",
  "eskerrak es plural, así que -zki-: eskerrak eman dizkiot (le he dado las gracias), eskerrak eman dizkizut. Por algo: -gatik: laguntzagatik.": "eskerrak est au pluriel, donc -zki- : eskerrak eman dizkiot (je l'ai remercié), eskerrak eman dizkizut. Pour quelque chose : -gatik : laguntzagatik.",
  "A vosotros: dizue, dizkizuet": "À vous : dizue, dizkizuet",
  "bidaliko dizuet (os enviaré una cosa), bidaliko dizkizuet (os enviaré varias). Y ellos a nosotros: digute, gonbidatu gaituzte (nos han invitado, sin dativo).": "bidaliko dizuet (je vous enverrai une chose), bidaliko dizkizuet (je vous en enverrai plusieurs). Et eux à nous : digute ; gonbidatu gaituzte (ils nous ont invités, sans datif).",
  "¿Has llamado a mamá?": "Tu as appelé maman ?",
  "Le he enviado un mensaje, pero no me ha contestado.": "Je lui ai envoyé un message, mais elle ne m'a pas répondu.",
  "Llámala, mejor. Anoche me llamó a mí y estaba muy contenta.": "Appelle-la plutôt. Hier soir elle m'a appelé(e) et elle était très contente.",
  "Vale, la llamo enseguida.": "D'accord, je l'appelle tout de suite.",
  "En la tienda: ¿me da…?": "Au magasin : vous me mettez… ?",
  "Emango didazu · zenbat zor dizut · lagunduko dizut": "Emango didazu · zenbat zor dizut · lagunduko dizut",
  "Gasteizko azokan · en el mercado de Vitoria": "Gasteizko azokan · au marché de Vitoria",
  "___ emango didazu? · zenbat zor dizut?": "___ emango didazu? · zenbat zor dizut?",
  "¿me da…?": "vous me donnez… ?",
